'use strict';

// MODULES //

var proxyquire = require( 'proxyquire' );
var tape = require( 'tape' );
var noop = require( '@stdlib/utils/noop' );
var Complex128Array = require( '@stdlib/array/complex128' );
var logEachMap = require( './../lib' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof logEachMap, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function throws an error if not provided at least 3 arguments', function test( t ) {
	var values;
	var i;

	values = [
		[],
		[ '%d' ],
		[ '%d', [1, 2, 3] ]
	];

	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[i] ), TypeError, 'throws an error when provided '+values[i].length+' arguments' );
	}
	t.end();

	function badValue( args ) {
		return function badValue() {
			logEachMap.apply( null, args );
		};
	}
});

tape( 'the function throws an error if not provided a string for the first argument', function test( t ) {
	var values;
	var i;

	values = [
		5,
		NaN,
		true,
		false,
		null,
		void 0,
		{},
		[],
		function noop() {}
	];

	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[i] ), TypeError, 'throws an error when provided '+values[i] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			logEachMap( value, [1, 2, 3], noop );
		};
	}
});

tape( 'the function throws an error if the provided callback is not a function', function test( t ) {
	var values;
	var i;

	values = [
		'5',
		5,
		NaN,
		true,
		false,
		null,
		void 0,
		{},
		[]
	];

	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[i] ), TypeError, 'throws an error when provided '+values[i] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			logEachMap( '%d', [1, 2, 3], value );
		};
	}
});

tape( 'the function throws an error if provided collections of unequal length', function test( t ) {
	t.throws( foo, Error, 'throws an error' );
	t.end();

	function foo() {
		logEachMap( '%d %d', [ 1, 2, 3 ], [ 1, 2 ], noop );
	}
});

tape( 'the function supports array-like objects', function test( t ) {
	var x;

	x = new Complex128Array( [ 1.0, 1.0, 2.0, 2.0, 3.0, 3.0 ] );
	t.doesNotThrow( foo, 'does not throw' );
	t.end();

	function foo() {
		logEachMap( '%d', x, noop );
	}
});

tape( 'the function inserts array element values into a format string, applies a callback, and prints the result (one array)', function test( t ) {
	var logEachMap;
	var expected;
	var actual;
	var x;

	logEachMap = proxyquire( './../lib/main.js', {
		'@stdlib/console/log': logger
	});

	x = [ 1, 2, 3 ];
	expected = [ '1 -> 2', '2 -> 4', '3 -> 6' ];
	actual = [];

	logEachMap( '%d -> %d', x, scale );

	t.deepEqual( actual, expected, 'returns expected mapped values' );
	t.end();

	function scale( v ) {
		return v * 2;
	}

	function logger( str ) {
		actual.push( str );
	}
});

tape( 'the function inserts array element values into a format string, applies a callback, and prints the result (two arrays)', function test( t ) {
	var logEachMap;
	var expected;
	var actual;
	var x;
	var y;

	logEachMap = proxyquire( './../lib/main.js', {
		'@stdlib/console/log': logger
	});

	x = [ 1, 2, 3 ];
	y = [ 4, 5, 6 ];
	expected = [ '1 + 4 = 5', '2 + 5 = 7', '3 + 6 = 9' ];
	actual = [];

	logEachMap( '%d + %d = %d', x, y, sum );

	t.deepEqual( actual, expected, 'returns expected mapped values' );
	t.end();

	function sum( v1, v2 ) {
		return v1 + v2;
	}

	function logger( str ) {
		actual.push( str );
	}
});

